// Oeste Gallery — Huntington theme (v0.2.0).
// Copy-paste ready. Requires: React 18+, Tailwind with arbitrary values, JSX transform.
// Requires Huntington tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/huntington/src/index.js
// Docs: https://oeste.hiddeninwest.com/huntington/#/components/gallery

export function Gallery({ title, count, images = [] }) {
  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-baseline gap-1.5">
        <h3 className="m-0 text-[13px] font-bold leading-[1] text-[var(--color-ink)]">{title}</h3>
        {count !== undefined && <span className="text-[13px] leading-[1] text-[var(--color-muted)]">{count}</span>}
      </div>
      <div className="grid grid-cols-3 gap-2">
        {images.map((src, i) => (
          <img key={i} src={src} alt="" className="aspect-square w-full rounded-[10px] border border-[var(--color-border)] object-cover" />
        ))}
      </div>
    </div>
  );
}
